module.TransferCode:
def can_start_fan(mode, air_quality_ok, smoke_alarm):
    return mode == "AUTO" and air_quality_ok and not smoke_alarm

def log_event(message):
    with open("ventilation.log", "a") as file:
        file.write(message + "\n")

mode = "AUTO"
air_quality_ok = True
smoke_alarm = False
fan_running = False

if can_start_fan(mode, air_quality_ok, smoke_alarm):
    fan_running = True
    log_event("Fan started")
    for cycle in range(1, 4):
        if smoke_alarm:
            fan_running = False
            log_event("Smoke shutdown")
            break
        print(f"Air-quality cycle {cycle}")
else:
    log_event("Fan start blocked")
